'use strict';
const DrillJournal=(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const avatar=n=>'<span class="discussion-avatar">'+(/^api\/stats\/avatars\/\d+\/[a-f0-9]+$/.test(n.avatar||'')?'<img src="'+esc(n.avatar)+'" width="36" height="36" loading="lazy" alt="'+esc(n.name)+'的头像">':esc(n.name?.slice(0,1)||'队'))+'</span>';
 function note(n,me,history=false){return '<article class="drill-note">'+avatar(n)+'<div class="drill-note-main"><header><strong>'+esc(n.name)+'</strong><small>#'+n.number+'</small>'+(history?'<time>'+esc(n.heldOn||'日期未设置')+' · '+esc(n.trainingName)+'</time>':'')+'</header>'+(n.problems?'<section><b>存在的问题</b><p>'+esc(n.problems)+'</p></section>':'')+(n.progress?'<section class="drill-note-progress"><b>相比上次的进步</b><p>'+esc(n.progress)+'</p></section>':'')+(!history&&me?.id===n.player?'<button type="button" class="drill-note-edit" data-edit-note="'+n.id+'">编辑我的记录</button>':'')+'</div></article>';}
 function init(d){
  const views=new Map();let historyId=null,historyHost=null,historyToken=0;
  function renderTraining(host,training,editable,revision){const key=training.id+':'+(d.getMe()?.id||'guest');let view=views.get(host.id);if(!view||view.key!==key){host.replaceChildren();view={key,cards:new Map()};views.set(host.id,view);}const ids=new Set(training.drills.map(x=>x.id));for(const [id,card] of view.cards)if(!ids.has(id)){card.el.remove();view.cards.delete(id);}
   if(!ids.size){host.innerHTML='<p class="stats-empty">还没有安排 Drill。</p>';return;}
   [...host.children].find(el=>el.classList.contains('stats-empty'))?.remove();
   for(const drill of training.drills){let card=view.cards.get(drill.id);if(!card){card=mountCard(host,view,training,drill);view.cards.set(drill.id,card);}card.update(drill,editable,revision);}
  }
  function mountCard(host,view,training,drill){const el=document.createElement('article');el.className='training-drill-card';el.dataset.drillJournal=drill.id;
   el.innerHTML='<div class="stats-drill-row"><span class="stats-drill-icon" aria-hidden="true">▶</span><strong></strong><button type="button" class="quiet-btn" data-team-drill="'+esc(drill.id)+'">查看演示</button><button type="button" class="quiet-btn danger-text" data-drill-remove="'+esc(drill.id)+'">移除</button></div><details class="drill-note-details"><summary>练习备注 <small data-j="count"></small></summary><div data-j="notes" class="drill-note-list"></div><p data-j="error" class="discussion-status" role="status"></p><button type="button" class="quiet-btn" data-j="login">登录队员身份后记录</button><form class="drill-note-form" data-j="form"><label>这次普遍存在的问题<textarea data-j="problems" maxlength="800" rows="2" placeholder="例如：切入偏早、回传后的清空不及时"></textarea></label><label>相比上次进步的地方<textarea data-j="progress" maxlength="800" rows="2" placeholder="例如：沟通更及时，接盘后的观察更充分"></textarea></label><button type="submit" class="quiet-btn" data-j="save">保存我的记录</button></form></details>';
   host.append(el);const $=s=>el.querySelector(s),details=$('details');let notes=[],signature='',loaded='',loading=false,pending=false,dirty=false,serial=0,ownId=null;const current=()=>views.get(host.id)===view&&el.parentElement===host;
   function draw(){const me=d.getMe();$('[data-j="notes"]').innerHTML=notes.length?notes.map(n=>note(n,me)).join(''):'<p class="stats-empty">还没有练习备注。</p>';ownId=notes.find(n=>n.player===me?.id)?.id||null;$('[data-j="save"]').textContent=pending?'正在保存…':ownId?'更新我的记录':'保存我的记录';}
   function hydrate(){if(dirty)return;const own=notes.find(n=>n.player===d.getMe()?.id);if(own){$('[data-j="problems"]').value=own.problems;$('[data-j="progress"]').value=own.progress;}}
   for(const input of el.querySelectorAll('textarea'))input.oninput=()=>dirty=true;
   async function load(){if(loading||pending)return;loading=true;const version=signature,request=++serial;$('[data-j="error"]').textContent='正在读取练习备注…';try{const result=await d.api('stats/trainings/'+training.id+'/drills/'+drill.id+'/notes');if(!current()||request!==serial)return;notes=result.notes;loaded=version;draw();hydrate();$('[data-j="error"]').textContent='';}catch(error){if(current())$('[data-j="error"]').textContent=error.message;}finally{loading=false;}}
   details.ontoggle=()=>{if(details.open)load();};$('[data-j="login"]').onclick=()=>d.login();
   el.onclick=event=>{const button=event.target.closest('[data-edit-note]');if(!button)return;const found=notes.find(n=>n.id===Number(button.dataset.editNote));if(!found||found.player!==d.getMe()?.id)return;$('[data-j="problems"]').value=found.problems;$('[data-j="progress"]').value=found.progress;$('[data-j="form"]').scrollIntoView({block:'nearest',behavior:'smooth'});};
   $('[data-j="form"]').onsubmit=async event=>{event.preventDefault();if(pending||!d.getMe())return;const problems=$('[data-j="problems"]').value.trim(),progress=$('[data-j="progress"]').value.trim();if(!problems&&!progress){$('[data-j="error"]').textContent='请至少填写一个问题或一项进步。';return;}pending=true;for(const input of el.querySelectorAll('textarea,button[data-j="save"]'))input.disabled=true;draw();try{const result=await d.api('stats/trainings/'+training.id+'/drills/'+drill.id+'/notes',{method:'POST',body:JSON.stringify({problems,progress})});if(current()){notes=result.notes;dirty=false;hydrate();$('[data-j="error"]').textContent='已保存，可在这个 Drill 的训练记录中回看。';}await d.refresh(true);d.toast('练习备注已保存。');}catch(error){if(current())$('[data-j="error"]').textContent=error.message;d.toast(error.message);}finally{pending=false;if(current()){for(const input of el.querySelectorAll('textarea,button[data-j="save"]'))input.disabled=false;draw();}}};
   return{el,update(next,editable,revision){$('.stats-drill-row>strong').textContent=next.name;$('[data-drill-remove]').hidden=!editable;$('[data-j="count"]').textContent=next.noteCount?'· '+next.noteCount+' 份记录':'';$('[data-j="form"]').hidden=!d.getMe();$('[data-j="login"]').hidden=!!d.getMe();signature=String(revision)+':'+(next.noteVersion||0);if(details.open&&loaded!==signature)load();}};
  }
  function expand(host,id){const el=[...host.querySelectorAll('[data-drill-journal]')].find(x=>x.dataset.drillJournal===id);if(el){el.querySelector('details').open=true;el.scrollIntoView({block:'start',behavior:'smooth'});}}
  function renderHistory(host,id){if(!host)return;if(historyHost===host&&historyId===id)return;historyHost=host;historyId=id;const token=++historyToken;host.hidden=!id;host.replaceChildren();if(!id)return;
   host.innerHTML='<details class="drill-history-details"><summary>训练记录 <small data-j="sessions"></small></summary><div class="drill-note-list" data-j="history"></div><p class="discussion-status" data-j="history-status" role="status"></p><button type="button" class="quiet-btn" data-j="more" hidden>加载更早的记录</button></details>';
   const $=s=>host.querySelector(s);let pending=false,offset=0,notes=[];
   async function load(reset=false){if(pending)return;pending=true;$('[data-j="history-status"]').textContent='正在读取训练记录…';if(reset){offset=0;notes=[];}try{const result=await d.api('stats/drills/'+id+'/notes?offset='+offset);if(token!==historyToken)return;notes=[...notes,...result.notes].filter((n,i,all)=>all.findIndex(x=>x.id===n.id)===i);$('[data-j="history"]').innerHTML=notes.length?notes.map(n=>note(n,d.getMe(),true)).join(''):'<p class="stats-empty">还没有训练记录。把这个 Drill 添加到训练后，队员可记录问题和进步。</p>';$('[data-j="sessions"]').textContent='· '+result.trainingCount+' 次训练';offset=result.nextOffset;$('[data-j="more"]').hidden=offset===null;$('[data-j="history-status"]').textContent='';}catch(error){if(token===historyToken)$('[data-j="history-status"]').textContent=error.message;}finally{pending=false;}}
   $('details').ontoggle=()=>{if(token===historyToken&&$('details')?.open)load(true);};$('[data-j="more"]').onclick=()=>load();
  }
  return{renderTraining,expand,renderHistory};
 }
 return{init};
})();
